// Reproduce the old incomplete prepared fixture. This is a diagnostic FAIL,
// never the qualifying peer bench and never a change to its watchdog.
#include "bench_peer_base.hpp"
#define D(n) b.d.rootp->cs88_pipeline_v91k__DOT__##n
int main(int argc,char**argv){try{
 need(argc==7,"diagnostic usage");auto cases=load(argv[1]);load_tiles(argv[2]);const Case*good=nullptr;for(const auto&c:cases)if(!c.error&&!c.dense[0].empty()&&!c.qvalid){good=&c;break;}need(good,"diagnostic fixture");Bench b(unsigned(std::stoul(argv[4])),argv[5],argv[3],argv[6]);
 b.prepare(*good,0,false);b.preload(*good);b.begin(*good);b.feed_until(16);for(unsigned k=0;!(b.d.queue_count==1&&b.d.queue_pending);++k){need(k<100,"diagnostic queue setup");b.tick();}
 D(transform__DOT__error)=5;D(transform__DOT__fault_o)=1;D(transform__DOT__fault_pending_o)=!D(inverse_fault_ack);b.d.eval();b.tick();b.tick();bool watchdog=false;
 try{b.settle();}catch(const std::runtime_error&e){need(std::string(e.what())=="ownership drain watchdog","different diagnostic failure");watchdog=true;}
 need(watchdog,"old invalid fixture did not reproduce watchdog");
 std::cout<<"{\"type\":\"diagnostic_verdict\",\"status\":\"FAIL_REPRODUCED_OLD_INCOMPLETE_FIXTURE\",\"failure\":\"ownership drain watchdog\",\"watchdog_edges\":200000,\"cycle\":"<<b.cycle<<",\"busy\":"<<unsigned(b.d.busy)<<",\"start_ready\":"<<unsigned(b.d.start_ready)<<",\"owner_open\":"<<unsigned(D(owner_open))<<",\"admission_credit\":"<<unsigned(D(admission_credit))<<",\"all_available\":"<<unsigned(D(all_available))<<",\"base_busy\":"<<unsigned(D(base_busy))<<",\"base_start_ready\":"<<unsigned(D(base_start_ready))<<",\"inverse_busy\":"<<unsigned(b.d.inverse_busy)<<",\"inverse_running\":"<<unsigned(D(transform__DOT__running))<<",\"inverse_fault\":"<<unsigned(D(transform__DOT__fault_o))<<",\"inverse_owned_banks\":"<<unsigned(b.d.inverse_owned_banks)<<",\"inverse_math_state\":"<<unsigned(D(transform__DOT__math_state))<<",\"inverse_accept_state\":"<<unsigned(D(transform__DOT__accept_state))<<",\"inverse_result0\":"<<unsigned(D(transform__DOT__result_state)[0])<<",\"inverse_result1\":"<<unsigned(D(transform__DOT__result_state)[1])<<",\"reconstruct_busy\":"<<unsigned(b.d.reconstruct_busy)<<",\"reconstruct_running\":"<<unsigned(D(reconstruction__DOT__running))<<",\"queue_count\":"<<unsigned(b.d.queue_count)<<",\"queue_pending\":"<<unsigned(b.d.queue_pending)<<",\"queue_active\":"<<unsigned(b.d.queue_active)<<",\"scratch_outstanding\":"<<unsigned(b.d.dbg_scratch_outstanding)<<",\"external_scratch_owner\":"<<bool(b.pending)<<",\"ref_pending\":"<<unsigned(b.d.ref_pending)<<",\"external_reference_owner\":"<<bool(b.reference_pending)<<",\"coefficient_stage_occupied\":"<<unsigned(D(coefficient_stage_occupied))<<"}\n";
 need(D(transform__DOT__running)&&b.d.inverse_busy&&D(transform__DOT__fault_o)&&!b.pending&&!b.reference_pending&&!b.d.dbg_scratch_outstanding&&!b.d.ref_pending&&!b.d.queue_count&&!b.d.queue_pending,"diagnostic state differs from incomplete fixture diagnosis");return 0;
}catch(const std::exception&e){std::cerr<<"PEER_DIAGNOSTIC_ERROR "<<e.what()<<'\n';return 1;}}
